const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25 };

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const basePremiumForItem = (item: { type: string }): number => basePremiumsByType[item.type];

const isBlockOfAlikeComponents = (items: { type: string }[]): boolean =>
  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");

export const basePremium = (items: { type: string }[]): number => {
  if (isBlockOfAlikeComponents(items)) {
    return BLOCK_PREMIUM;
  }
  return items.reduce((sum, item) => sum + basePremiumForItem(item), 0);
};
